<?php
require_once __DIR__.'/../config/app.php';require_admin();$q=trim($_GET['q']??'');$params=[];$where="u.role='customer'";if($q!==''){$where.=' AND (u.name LIKE ? OR u.email LIKE ? OR u.phone LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like];}$stmt=db()->prepare("SELECT u.*,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.payment_status='paid' THEN o.total_amount ELSE 0 END),0) total_spent,MAX(o.created_at) last_order FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE $where GROUP BY u.id ORDER BY u.created_at DESC");$stmt->execute($params);$customers=$stmt->fetchAll();$pageTitle='Pelanggan';require APP_ROOT.'/includes/admin-header.php';
?>
<form class="d-flex gap-2 mb-4" style="max-width:520px"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Cari nama, email, atau nomor HP"><button class="btn btn-primary"><i class="bi bi-search"></i></button></form><div class="admin-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Pelanggan</th><th>Nomor HP</th><th>Terdaftar</th><th>Pesanan</th><th>Total belanja lunas</th><th>Pesanan terakhir</th></tr></thead><tbody><?php foreach($customers as $customer):?><tr><td><strong><?= e($customer['name']) ?></strong><div class="small text-muted"><?= e($customer['email']) ?></div></td><td><?= e($customer['phone']) ?></td><td><?= date('d M Y',strtotime($customer['created_at'])) ?></td><td><?= $customer['order_count'] ?></td><td><strong><?= rupiah($customer['total_spent']) ?></strong></td><td><?= $customer['last_order']?date('d M Y',strtotime($customer['last_order'])):'—' ?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require APP_ROOT.'/includes/admin-footer.php';?>
